?><!doctype html><html><body><main><p><a href="/owner-control/v1/index.php">Owner Control</a></p><h1>Lab Store Offers</h1><p id="status">Loading offer presentation…</p><section id="cards"></section></main><script>'use strict';const fields=['source_type','category','title','offer_active','source_available','presentation_ref','media_kind'],status=document.getElementById('status'),cards=document.getElementById('cards');function valid(o){return o&&typeof o==='object'&&Object.keys(o).every(k=>fields.includes(k))&&(o.source_type==='normal_store'||o.source_type==='genetic_item')&&typeof o.category==='string'&&typeof o.title==='string'&&typeof o.offer_active==='boolean'&&typeof o.source_available==='boolean'&&(typeof o.presentation_ref==='string'||o.presentation_ref===null)&&(o.media_kind==='image'||o.media_kind==='media_unavailable')}async function load(){try{const r=await fetch('/api/owner-control/v1/lab-store/offers.php',{credentials:'same-origin',cache:'no-store'}),p=await r.json();if(!r.ok||!p||p.success!==true||p.capability!=='owner_control_lab_store_offers_read'||p.mode!=='read_only'||p.writes!==false||!Array.isArray(p.offers)||!p.offers.every(valid))throw Error();const f=document.createDocumentFragment();for(const o of p.offers){const a=document.createElement('article'),h=document.createElement('h2'),m=document.createElement('p');h.textContent=o.title;m.textContent=o.category+' · '+(o.offer_active?'Active':'Inactive')+' · '+(o.source_available?'Available':'Unavailable');a.append(h,m);if(o.presentation_ref!==null){const i=document.createElement('img');i.src=o.presentation_ref;i.alt='';a.append(i)}f.append(a)}cards.replaceChildren(f);status.textContent=p.offers.length?'Read-only offer presentation loaded.':'No Lab Store offer presentation is available.'}catch(e){cards.replaceChildren();status.textContent='Lab Store offer presentation is currently unavailable.'}}load();</script></body></html>